/**
 * Interview questions by subject, with short answers written for OU All In One.
 * Each question has an id ("subject/slug") so company interview pages can link to it; the
 * "asked in" tags shown on the site are derived from those links (content/placements/interviews.mjs).
 */
const S = (id, title, blurb, qs) => ({ id, title, blurb, qs: qs.map(([slug, q, a]) => ({ id: `${id}/${slug}`, q, a })) });

export const SUBJECTS = [
  S('hr', 'HR and managerial', 'Introduction, motivation, strengths, situations and the questions every company asks.', [
    ['introduce-yourself', 'Tell me about yourself.', 'Keep it to about 90 seconds: your name and college, your branch and one or two strengths, your best project in one line (what it does and your part), one internship, certification or activity, and why you are interested in this role. Practise it aloud; it sets the tone for the rest of the interview.'],
    ['why-company', 'Why do you want to join our company?', 'Mention two specific things: something about the company (its training programme, the domains or clients it works in, its scale or recent work) and how it fits what you want to learn. Avoid answers only about salary or "it is a big company". Read the company\'s careers page before the interview.'],
    ['know-company', 'What do you know about our company?', 'Know the basics: what the company does (services, consulting, products), where it is headquartered, its CEO, roughly how many people it employs, and the roles it hires freshers for. One recent fact (a new service line, an acquisition, a big project) shows real interest.'],
    ['strengths-weaknesses', 'What are your strengths and weaknesses?', 'Give one or two strengths with a short example each (for example, learning quickly: "I learnt React in two weeks for my project"). For a weakness, pick a real but manageable one and say what you are doing about it ("I used to hesitate to speak in groups, so I started presenting in class seminars").'],
    ['five-years', 'Where do you see yourself in five years?', 'Show growth inside the company: becoming strong in a technology or domain, handling bigger responsibilities, perhaps leading a small module or team. Keep it realistic and connected to the role you are applying for.'],
    ['why-hire', 'Why should we hire you?', 'Connect your skills to the role in three points: technical basics you are confident in, a project or internship that proves it, and a quality such as consistency or teamwork. End with your willingness to learn whatever the project needs.'],
    ['explain-project', 'Explain your final-year project.', 'Cover the problem, who it helps, the technology you used and why, your own contribution, one difficulty you faced and how you solved it, and what you would improve. Expect follow-up questions on any word you say, so only mention tools you actually used.'],
    ['project-challenge', 'What difficulties did you face in your project and how did you solve them?', 'Pick one concrete problem (a bug, a performance issue, a teammate leaving, a deadline) and describe the steps you took and the result. Interviewers look for how you think and debug, not for a perfect project.'],
    ['relocate', 'Are you willing to relocate or work in shifts?', 'Service companies place freshers across India and in client time zones, so an honest "yes" helps a lot. If you have a real constraint, say it politely and early rather than refusing later.'],
    ['bond', 'Are you comfortable with the service agreement (bond)?', 'Several companies ask freshers to sign a service agreement. Read the offer terms before the interview and answer honestly; if you agree, say so clearly.'],
    ['handle-pressure', 'How do you handle pressure and tight deadlines?', 'Describe your method: break the work into small tasks, prioritise what matters most, communicate early if something will slip, and give an example from college (exams plus a project submission in the same week).'],
    ['team-conflict', 'How would you resolve a conflict in your team?', 'Listen to both sides privately, focus on the work rather than the people, agree on facts and a shared goal, and involve the lead only if it cannot be solved. A short example from a college team makes it believable.'],
    ['client-deadline', 'A client wants a deadline you know cannot be met. What do you do?', 'Do not just say yes. Explain the realistic timeline with reasons, offer options (deliver the most important part first, add people, reduce scope), and keep your manager informed. Clients value honesty more than missed promises.'],
    ['rejection', 'How do you handle rejection or failure?', 'Treat it as feedback: find what went wrong, improve it and try again. A short real example ("I was not selected in my first placement test, so I practised aptitude daily and cleared the next one") works well.'],
    ['time-management', 'How do you manage your time and prioritise tasks?', 'Explain a simple system: a daily to-do list, doing urgent and important work first, fixed time blocks for study, and reviewing at the end of the day. Mention a time you balanced several deadlines.'],
    ['cgpa-gap', 'Your marks dropped (or you have a backlog). Why?', 'Be honest and brief about the reason, then show what changed: how you recovered, what you learnt and what you built or achieved since. Do not blame others.'],
    ['learn-new', 'Are you open to learning a technology you have not used?', 'Yes, with proof: mention something you learnt on your own (a language, a framework, a certification) and how you approach learning (documentation, small practice projects, asking seniors).'],
    ['salary', 'What are your salary expectations?', 'For campus roles the package is usually fixed, so say you are comfortable with the company\'s standard offer for freshers and that learning and growth matter most to you at this stage.'],
    ['questions-for-us', 'Do you have any questions for us?', 'Always ask one or two: what training freshers get, what technologies the team uses, or what a typical first project looks like. Avoid asking about leave or salary in the first interview.'],
  ]),

  S('oop', 'OOP concepts', 'Classes, objects, the four pillars, overloading versus overriding, abstract classes and interfaces.', [
    ['what-is-oop', 'What is object-oriented programming?', 'A way of writing programs around objects, which bundle data (fields) and behaviour (methods). It helps model real things, reuse code and keep large programs organised. Java, C++ and Python all support it.'],
    ['class-object', 'What is the difference between a class and an object?', 'A class is a blueprint that describes fields and methods; an object is an instance created from that blueprint, with its own values. One Car class can create many car objects.'],
    ['pillars', 'What are the four pillars of OOP?', 'Encapsulation (keeping data and the methods that use it together, and hiding the data), abstraction (showing only what is needed and hiding details), inheritance (a class reusing another class\'s members) and polymorphism (one name, many forms, such as overloading and overriding). Be ready to give a small code example of each.'],
    ['encapsulation-abstraction', 'What is the difference between encapsulation and abstraction?', 'Encapsulation is about hiding data inside a class and controlling access through methods (private fields with getters and setters). Abstraction is about hiding complexity and exposing only the essential operations (an interface or abstract class). Encapsulation is how; abstraction is what.'],
    ['polymorphism', 'What is polymorphism? Overloading versus overriding?', 'Polymorphism lets the same call behave differently. Overloading (compile-time) means several methods with the same name but different parameters in one class. Overriding (run-time) means a subclass gives its own version of a parent method with the same signature, chosen based on the actual object.'],
    ['inheritance', 'What is inheritance and what types are there?', 'Inheritance lets a class acquire the fields and methods of another. Types: single, multilevel, hierarchical, multiple and hybrid. Java does not allow multiple inheritance of classes (it uses interfaces instead); C++ does.'],
    ['abstract-interface', 'What is the difference between an abstract class and an interface?', 'An abstract class can have fields, constructors and both abstract and normal methods, and a class can extend only one. An interface defines a contract of methods (in Java it can also have default and static methods but no instance state), and a class can implement many. Use an interface for a capability and an abstract class for shared base code.'],
    ['constructor', 'What is a constructor? Can it be overloaded?', 'A special method with the class name that runs when an object is created, used to initialise fields. It has no return type. Yes, constructors can be overloaded with different parameter lists.'],
    ['access-modifiers', 'What are access modifiers?', 'Keywords that control visibility: public (everywhere), private (only inside the class), protected (the class and its subclasses, plus the package in Java) and default/package-private in Java (only the same package).'],
    ['singleton', 'What is a singleton class?', 'A class that allows only one object. Make the constructor private, keep a static instance and return it from a static method such as getInstance(). Used for things like a configuration manager or a logger.'],
    ['this-super', 'What do this and super mean?', 'this refers to the current object (to access its fields or call another constructor). super refers to the parent class (to call the parent constructor or an overridden parent method).'],
  ]),

  S('c', 'C programming', 'Pointers, memory, storage classes, structures and the classic C viva questions.', [
    ['c-vs-cpp', 'What is the difference between C and C++?', 'C is a procedural language; C++ adds object-oriented features (classes, inheritance, polymorphism), references, function overloading, templates, exceptions and the STL. C++ is mostly a superset of C.'],
    ['pointer', 'What is a pointer?', 'A variable that stores the address of another variable. You get an address with & and read the value at an address with *. Pointers allow dynamic memory, efficient array handling and passing variables by reference.'],
    ['malloc-calloc', 'What is the difference between malloc and calloc? Static versus dynamic memory?', 'Static memory is fixed at compile time (normal arrays, globals). Dynamic memory is requested at run time from the heap. malloc(size) allocates a block without initialising it; calloc(n, size) allocates n elements and sets them to zero. Both return NULL on failure and must be released with free().'],
    ['dangling-null', 'What are dangling, null and wild pointers?', 'A null pointer points nowhere (NULL). A wild pointer is declared but never initialised. A dangling pointer still holds the address of memory that has been freed or has gone out of scope. Set pointers to NULL after free to avoid using them.'],
    ['memory-leak', 'What is a memory leak?', 'Dynamic memory that is allocated but never freed, so it cannot be used again while the program runs. Every malloc/calloc should have a matching free.'],
    ['call-by', 'What is call by value versus call by reference?', 'Call by value passes a copy, so changes inside the function do not affect the caller. Call by reference passes the address (a pointer in C), so the function can change the original variable, as in swap(&a, &b).'],
    ['storage-classes', 'What are the storage classes in C?', 'auto (default for local variables), register (a hint to keep it in a CPU register), static (keeps its value between function calls, or limits a global to one file) and extern (declares a variable defined in another file).'],
    ['struct-union', 'What is the difference between a structure and a union?', 'In a structure every member has its own memory, so the size is at least the sum of the members. In a union all members share the same memory, so the size equals the largest member and only one member holds a valid value at a time.'],
    ['double-float', 'What is the difference between float and double?', 'Both store decimal numbers. float usually takes 4 bytes with about 7 digits of precision; double takes 8 bytes with about 15–16 digits. Use double when accuracy matters.'],
    ['macro-function', 'What is the difference between a macro and a function?', 'A macro (#define) is replaced by the preprocessor before compilation, so there is no function-call cost but also no type checking. A function is compiled once and called at run time with type-checked arguments.'],
    ['include-forms', 'What is the difference between #include <file> and #include "file"?', 'Angle brackets search the standard system include folders (for library headers like stdio.h). Quotes search the current project folder first, then the system folders (for your own headers).'],
    ['recursion', 'What is recursion?', 'A function calling itself with a smaller input until it reaches a base case, such as factorial(n) = n × factorial(n − 1) with factorial(0) = 1. Without a base case it never stops and overflows the stack.'],
  ]),

  S('cpp', 'C++', 'Virtual functions, references, constructors, STL and memory in C++.', [
    ['virtual', 'What is a virtual function?', 'A member function declared with virtual in the base class so that a call through a base pointer or reference runs the derived class\'s version. This is run-time polymorphism, implemented with a virtual table (vtable).'],
    ['pure-virtual', 'What is a pure virtual function and an abstract class?', 'A pure virtual function is declared as virtual void f() = 0; and has no body in the base class. A class with at least one is abstract: it cannot be instantiated, and derived classes must override the function.'],
    ['reference-pointer', 'What is the difference between a reference and a pointer?', 'A reference is another name for an existing variable: it must be initialised, cannot be null and cannot be changed to refer to something else. A pointer holds an address, can be null, can be reassigned and supports pointer arithmetic.'],
    ['new-malloc', 'What is the difference between new and malloc?', 'new is an operator that allocates memory and calls the constructor, returns the correct type and throws on failure; it is released with delete. malloc is a C function that only allocates raw bytes, returns void* and NULL on failure; it is released with free.'],
    ['copy-constructor', 'What is a copy constructor? Shallow versus deep copy?', 'A constructor that creates an object from another object of the same class. The default one copies member by member (shallow), so two objects may share the same heap memory. A deep copy allocates new memory and copies the contents, which you need when a class owns pointers.'],
    ['destructor', 'What is a destructor and why make it virtual?', 'A destructor (~ClassName) runs when an object is destroyed and releases its resources. In a base class used polymorphically it should be virtual, so deleting a derived object through a base pointer calls the derived destructor too.'],
    ['stl', 'What is the STL? Name some containers.', 'The Standard Template Library provides containers (vector, list, deque, set, map, unordered_map, stack, queue), algorithms (sort, find, binary_search) and iterators. vector is a dynamic array with fast random access; list is a doubly linked list with fast insertion in the middle.'],
    ['templates', 'What are templates?', 'A way to write generic code that works with any type, such as template <typename T> T maxOf(T a, T b). The compiler generates a version for each type used. The STL is built on templates.'],
    ['inline', 'What is an inline function?', 'A request to the compiler to replace the function call with the function body to save call overhead. It suits very small functions; the compiler may ignore the request.'],
    ['friend', 'What is a friend function?', 'A non-member function (or class) given access to a class\'s private and protected members by declaring it with friend inside the class. Useful for operator overloading such as <<.'],
    ['smart-pointers', 'What are smart pointers?', 'Classes that manage a heap object and free it automatically: unique_ptr (single owner), shared_ptr (reference-counted shared ownership) and weak_ptr (non-owning link to a shared_ptr). They prevent memory leaks.'],
  ]),

  S('java', 'Java', 'JVM, strings, exceptions, collections, multithreading and the questions asked most in service company interviews.', [
    ['jdk-jre-jvm', 'What is the difference between JDK, JRE and JVM?', 'The JVM runs Java bytecode and makes Java platform-independent. The JRE is the JVM plus the standard libraries needed to run programs. The JDK is the JRE plus development tools such as the compiler (javac) and debugger.'],
    ['cpp-vs-java', 'What is the difference between C++ and Java?', 'Java compiles to bytecode that runs on the JVM (platform-independent); C++ compiles to native code. Java has automatic garbage collection, no explicit pointers and no multiple inheritance of classes; C++ has manual memory management, pointers, multiple inheritance and operator overloading.'],
    ['error-exception', 'What is the difference between an error and an exception?', 'Both extend Throwable. An Error is a serious problem the program usually should not try to handle, such as OutOfMemoryError or StackOverflowError. An Exception is a condition the program can catch and recover from, such as IOException or ArithmeticException.'],
    ['checked-unchecked', 'What are checked and unchecked exceptions?', 'Checked exceptions (IOException, SQLException) are checked at compile time and must be caught or declared with throws. Unchecked exceptions (subclasses of RuntimeException, such as NullPointerException or ArrayIndexOutOfBoundsException) are not checked by the compiler.'],
    ['try-catch-finally', 'How do try, catch and finally work? Does finally always run?', 'try holds code that may throw, catch handles a matching exception, and finally runs whether or not an exception occurred, even after a return in try. It is skipped only if the JVM stops (for example System.exit). If finally has its own return, that value wins, which is a common output question.'],
    ['final-finally-finalize', 'What is the difference between final, finally and finalize?', 'final is a keyword: a final variable cannot be reassigned, a final method cannot be overridden, a final class cannot be extended. finally is the block after try/catch that always runs. finalize() was a method called by the garbage collector before removing an object; it is deprecated.'],
    ['string-immutable', 'Why are strings immutable? String versus StringBuilder versus StringBuffer?', 'String objects cannot change, which makes them safe to share, cache in the string pool and use as map keys. StringBuilder is mutable and fast for building strings in one thread; StringBuffer is mutable and synchronised (thread-safe) but slower.'],
    ['equals', 'What is the difference between == and equals()?', '== compares references (whether both variables point to the same object; for primitives it compares values). equals() compares contents when the class overrides it, as String does. If you override equals, override hashCode too.'],
    ['static', 'What does static mean?', 'A static member belongs to the class rather than to objects: one shared copy, accessed with the class name. Static methods cannot use this or non-static members directly. main is static so the JVM can call it without creating an object.'],
    ['garbage-collection', 'What is garbage collection?', 'The JVM automatically frees memory used by objects that are no longer reachable from any live reference. You cannot force it; System.gc() is only a request. It removes the need for manual free/delete.'],
    ['arraylist-linkedlist', 'What is the difference between ArrayList and LinkedList?', 'ArrayList is backed by a resizable array: fast random access by index, slower insertion and removal in the middle. LinkedList is a doubly linked list: fast insertion and removal at known positions, slow access by index.'],
    ['hashmap', 'How does a HashMap work?', 'It stores key-value pairs in an array of buckets. The key\'s hashCode() picks the bucket and equals() finds the right key inside it. Collisions are kept in a list (turned into a tree when a bucket gets large). It allows one null key and is not thread-safe; use ConcurrentHashMap for that.'],
    ['collections', 'What is the Collections framework?', 'A set of interfaces and classes for groups of objects: List (ArrayList, LinkedList), Set (HashSet, TreeSet), Queue (PriorityQueue, ArrayDeque) and Map (HashMap, TreeMap). Collection is the root interface; Collections is a utility class with methods like sort.'],
    ['threads', 'How do you create a thread? Thread versus Runnable?', 'Either extend Thread and override run(), or implement Runnable and pass it to a Thread, then call start() (not run()). Implementing Runnable is preferred because the class can still extend another class. Executors and thread pools are used in real projects.'],
    ['synchronization', 'What is synchronisation?', 'Controlling access to shared data so only one thread uses it at a time, using synchronized methods or blocks (or locks). It prevents race conditions but can cause deadlock if locks are taken in different orders.'],
    ['serialization', 'What is serialisation?', 'Converting an object into a byte stream so it can be saved to a file or sent over a network, and later rebuilt (deserialisation). A class must implement Serializable; fields marked transient are skipped.'],
    ['streams-lambda', 'What are lambdas and streams (Java 8)?', 'A lambda is a short anonymous function, such as (a, b) -> a + b, used with functional interfaces. Streams process collections in a pipeline: list.stream().filter(x -> x > 10).map(x -> x * 2).collect(Collectors.toList()). They make code shorter and easy to parallelise.'],
    ['spring-boot', 'What is Spring Boot? Name some annotations.', 'A framework that makes it quick to build Java web applications and REST APIs with auto-configuration and an embedded server. Common annotations: @SpringBootApplication, @RestController, @GetMapping/@PostMapping, @Autowired (dependency injection), @Service, @Repository and @Entity.'],
  ]),

  S('python', 'Python', 'Data types, mutability, functions, decorators, generators and pandas basics.', [
    ['list-tuple', 'What is the difference between a list and a tuple?', 'A list is mutable (you can add, remove and change items) and written with []. A tuple is immutable and written with (). Tuples are slightly faster, can be dictionary keys and suit fixed data such as coordinates.'],
    ['mutable', 'Which Python types are mutable and immutable?', 'Mutable: list, dict, set and most user-defined objects. Immutable: int, float, bool, str, tuple and frozenset. Changing an immutable value actually creates a new object.'],
    ['dict', 'How does a dictionary work?', 'It stores key-value pairs in a hash table, giving average O(1) lookup by key. Keys must be hashable (immutable). Since Python 3.7 dictionaries keep insertion order.'],
    ['args-kwargs', 'What are *args and **kwargs?', '*args collects extra positional arguments into a tuple; **kwargs collects extra keyword arguments into a dictionary. They let a function accept a variable number of arguments.'],
    ['is-equals', 'What is the difference between is and ==?', '== compares values; is checks whether both names refer to the same object in memory. Use is for None checks (x is None).'],
    ['comprehension', 'What is a list comprehension?', 'A compact way to build a list: [x * x for x in range(10) if x % 2 == 0] gives the squares of even numbers. There are also set and dictionary comprehensions.'],
    ['decorator', 'What is a decorator?', 'A function that takes another function and returns a new function that adds behaviour around it (logging, timing, access checks). Applied with @decorator_name above the function definition.'],
    ['generator', 'What is a generator?', 'A function that uses yield to produce values one at a time, keeping its state between calls. It saves memory for large sequences because values are created only when needed.'],
    ['copy', 'What is the difference between a shallow copy and a deep copy?', 'A shallow copy (copy.copy, list.copy()) creates a new outer object but shares the inner objects. A deep copy (copy.deepcopy) copies everything recursively, so changes to nested items do not affect the original.'],
    ['self-init', 'What are self and __init__?', '__init__ is the constructor method that runs when an object is created and sets up its attributes. self is the first parameter of instance methods and refers to the object itself.'],
    ['lambda', 'What is a lambda function?', 'A small anonymous function written in one expression: square = lambda x: x * x. Often used with sorted, map and filter, for example sorted(items, key=lambda p: p[1]).'],
    ['exceptions', 'How does exception handling work in Python?', 'Code that may fail goes in try; except catches specific errors; else runs if no error happened; finally always runs (for cleanup). raise throws an exception yourself.'],
    ['gil', 'What is the GIL?', 'The Global Interpreter Lock in CPython lets only one thread run Python bytecode at a time. Threads still help for waiting on I/O, but for CPU-heavy work you use multiprocessing.'],
    ['pandas', 'What are pandas Series and DataFrame?', 'pandas is a data-analysis library. A Series is a one-dimensional labelled column; a DataFrame is a table of rows and columns. Common operations: read_csv, head, groupby, merge, fillna and filtering rows with conditions such as df[df.marks > 60].'],
  ]),

  S('dsa', 'Data structures and algorithms', 'Arrays, linked lists, stacks, queues, trees, searching, sorting and complexity.', [
    ['array-linkedlist', 'What is the difference between an array and a linked list?', 'An array stores elements in contiguous memory with a fixed size (in C) and gives O(1) access by index, but inserting in the middle is O(n). A linked list stores nodes connected by pointers, grows dynamically and inserts in O(1) at a known node, but access by position is O(n).'],
    ['stack-queue', 'What is the difference between a stack and a queue?', 'A stack is LIFO (last in, first out): push and pop at one end, used for function calls, undo and bracket matching. A queue is FIFO (first in, first out): insert at the rear and remove from the front, used for scheduling and BFS.'],
    ['complexity', 'What is time complexity? What does O(n) mean?', 'Time complexity describes how running time grows with input size n. O(1) is constant, O(log n) logarithmic (binary search), O(n) linear (one loop), O(n log n) (merge sort) and O(n²) (nested loops). Space complexity measures extra memory in the same way.'],
    ['binary-search', 'How does binary search work?', 'On a sorted array, compare the target with the middle element; if smaller, search the left half, if larger the right half, and repeat. Each step halves the range, so it takes O(log n) time.'],
    ['sorting', 'Compare common sorting algorithms.', 'Bubble, selection and insertion sort are O(n²) (insertion is fast on nearly sorted data). Merge sort is O(n log n) always and stable but needs extra memory. Quick sort is O(n log n) on average, O(n²) in the worst case, and sorts in place. Heap sort is O(n log n) in place.'],
    ['hashing', 'What is hashing?', 'Mapping a key to an index in a table using a hash function, giving average O(1) insert and lookup. When two keys land in the same slot (a collision) they are handled by chaining (a list per slot) or open addressing (probing for another slot).'],
    ['bst', 'What is a binary search tree?', 'A binary tree where every node\'s left subtree has smaller keys and right subtree larger keys. Search, insert and delete take O(log n) when balanced and O(n) when skewed. An in-order traversal gives sorted order.'],
    ['traversals', 'What are tree traversals? BFS versus DFS?', 'Depth-first traversals of a tree are in-order (left, root, right), pre-order (root, left, right) and post-order (left, right, root). BFS visits level by level using a queue; DFS goes deep first using recursion or a stack.'],
    ['reverse-list', 'How do you reverse a linked list?', 'Walk the list with three pointers (previous, current, next): save next, point current back to previous, move previous and current one step forward. When current becomes null, previous is the new head. O(n) time, O(1) space.'],
    ['detect-loop', 'How do you detect a loop in a linked list?', 'Floyd\'s method: move a slow pointer one step and a fast pointer two steps at a time. If they ever meet there is a cycle; if fast reaches null there is none.'],
    ['recursion-iteration', 'What is the difference between recursion and iteration?', 'Recursion solves a problem by calling the function on smaller inputs, which is natural for trees and divide-and-conquer but uses stack memory. Iteration uses loops and constant extra memory. Any recursion can be rewritten iteratively, sometimes with an explicit stack.'],
    ['dynamic-programming', 'What is dynamic programming?', 'Solving a problem by breaking it into overlapping subproblems and storing their answers so each is computed once, either top-down with memoisation or bottom-up with a table. Examples: Fibonacci, knapsack, longest common subsequence, coin change.'],
  ]),

  S('dbms', 'DBMS', 'Keys, normalisation, ACID, transactions, indexing and the database theory interviewers ask.', [
    ['dbms-rdbms', 'What is a DBMS? How is an RDBMS different?', 'A DBMS is software for storing, retrieving and managing data (with security, backup and concurrent access). An RDBMS stores data in related tables with rows and columns, uses keys to link tables and SQL to query them: MySQL, PostgreSQL, Oracle, SQL Server.'],
    ['keys', 'What is the difference between a primary key and a foreign key?', 'A primary key uniquely identifies each row in a table and cannot be NULL; a table has one. A foreign key is a column that refers to the primary key of another table, linking the tables and enforcing referential integrity; it can repeat and can be NULL.'],
    ['other-keys', 'What are candidate, super, unique and composite keys?', 'A super key is any set of columns that uniquely identifies a row. A candidate key is a minimal super key; one is chosen as the primary key. A unique key also enforces uniqueness but allows a NULL. A composite key is a key made of two or more columns.'],
    ['normalization', 'What is normalisation? Explain 1NF, 2NF, 3NF and BCNF.', 'Organising tables to reduce duplicate data and update anomalies. 1NF: atomic values, no repeating groups. 2NF: 1NF and no partial dependency on part of a composite key. 3NF: 2NF and no transitive dependency (non-key columns depend only on the key). BCNF: every determinant is a candidate key.'],
    ['acid', 'What are the ACID properties?', 'Atomicity (a transaction happens completely or not at all), Consistency (it moves the database from one valid state to another), Isolation (concurrent transactions do not interfere) and Durability (once committed, changes survive a crash). A bank transfer is the usual example.'],
    ['transaction', 'What is a transaction? COMMIT versus ROLLBACK?', 'A group of operations treated as one unit of work. COMMIT saves all its changes permanently; ROLLBACK undoes them back to the start (or to a SAVEPOINT).'],
    ['indexing', 'What is an index and why is it used?', 'A data structure (usually a B-tree) that lets the database find rows quickly without scanning the whole table, like a book\'s index. It speeds up searches and joins but uses extra space and slows inserts and updates. Primary keys are indexed automatically.'],
    ['view', 'What is a view?', 'A virtual table defined by a saved SELECT query. It stores no data itself; it simplifies complex queries and can restrict which columns users see.'],
    ['er-model', 'What is an ER diagram?', 'An entity-relationship diagram models a database: entities (tables) as rectangles, attributes as ovals and relationships (one-to-one, one-to-many, many-to-many) as diamonds. It is drawn before creating tables.'],
    ['ddl-dml', 'What are DDL, DML, DCL and TCL?', 'DDL defines structure (CREATE, ALTER, DROP, TRUNCATE). DML changes data (INSERT, UPDATE, DELETE; SELECT is often grouped here). DCL controls access (GRANT, REVOKE). TCL controls transactions (COMMIT, ROLLBACK, SAVEPOINT).'],
    ['sql-nosql', 'What is the difference between SQL and NoSQL databases?', 'SQL databases are relational, with fixed schemas, tables and strong consistency (MySQL, PostgreSQL). NoSQL databases store documents, key-value pairs, wide columns or graphs with flexible schemas and scale out easily (MongoDB, Redis, Cassandra, Firestore).'],
  ]),

  S('sql', 'SQL', 'Query writing: joins, GROUP BY with HAVING, second-highest salary, DELETE versus TRUNCATE versus DROP, and query writing.', [
    ['delete-truncate-drop', 'What is the difference between DELETE, TRUNCATE and DROP?', 'DELETE removes chosen rows (with WHERE), is logged row by row and can be rolled back. TRUNCATE removes all rows quickly, keeps the table structure and usually resets auto-increment. DROP removes the whole table, structure included.'],
    ['joins', 'What are the types of joins?', 'INNER JOIN returns rows with matches in both tables. LEFT JOIN returns all rows from the left table plus matches (NULL where none). RIGHT JOIN is the mirror. FULL OUTER JOIN returns all rows from both. CROSS JOIN returns every combination. A self join joins a table to itself, for example employees to their managers.'],
    ['join-query', 'Write a query to show each employee with their department name.', 'SELECT e.name, d.dept_name FROM employees e INNER JOIN departments d ON e.dept_id = d.id; Use LEFT JOIN instead if employees without a department must also appear.'],
    ['where-having', 'What is the difference between WHERE and HAVING?', 'WHERE filters rows before grouping and cannot use aggregate functions. HAVING filters groups after GROUP BY and can use aggregates: SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id HAVING COUNT(*) > 5;'],
    ['highest-salary', 'Find the employee with the highest salary.', 'SELECT name, salary FROM employees WHERE salary = (SELECT MAX(salary) FROM employees); This returns everyone who shares the top salary. ORDER BY salary DESC LIMIT 1 returns just one row.'],
    ['second-highest', 'Find the second-highest salary.', 'SELECT MAX(salary) FROM employees WHERE salary < (SELECT MAX(salary) FROM employees); For the Nth highest: SELECT DISTINCT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET N-1; or use DENSE_RANK() in a subquery.'],
    ['duplicates', 'How do you find duplicate rows?', 'Group by the columns that should be unique and keep groups with more than one row: SELECT email, COUNT(*) FROM users GROUP BY email HAVING COUNT(*) > 1;'],
    ['union', 'What is the difference between UNION and UNION ALL?', 'Both combine the results of two SELECTs with the same number and types of columns. UNION removes duplicate rows (slower); UNION ALL keeps every row (faster).'],
    ['group-by', 'What does GROUP BY do?', 'It groups rows that share a value so aggregate functions (COUNT, SUM, AVG, MIN, MAX) work per group: SELECT dept_id, AVG(salary) FROM employees GROUP BY dept_id; Every selected column must be grouped or aggregated.'],
    ['constraints', 'What are constraints in SQL?', 'Rules on columns: NOT NULL, UNIQUE, PRIMARY KEY, FOREIGN KEY, CHECK (a condition such as age >= 18) and DEFAULT (a value used when none is given).'],
    ['count', 'What is the difference between COUNT(*) and COUNT(column)?', 'COUNT(*) counts all rows; COUNT(column) counts rows where that column is not NULL; COUNT(DISTINCT column) counts unique non-NULL values.'],
    ['subquery', 'What is a subquery? When would you use a join instead?', 'A query inside another query, used in WHERE, FROM or SELECT (as in the second-highest salary query). A correlated subquery runs once per outer row. Joins are often faster for combining columns from several tables.'],
    ['sql-mysql', 'What is the difference between SQL and MySQL?', 'SQL is the language for querying relational databases. MySQL is one database system (an RDBMS) that uses SQL, like PostgreSQL or Oracle.'],
    ['window', 'What are window functions?', 'Functions that calculate across a set of related rows without collapsing them, using OVER(): ROW_NUMBER(), RANK(), DENSE_RANK(), and running totals with SUM(...) OVER (ORDER BY ...). Handy for top-N per group.'],
  ]),

  S('os', 'Operating systems', 'Processes, threads, scheduling, deadlock, memory management and synchronisation.', [
    ['what-os', 'What is an operating system? What is the kernel?', 'Software that manages hardware and provides services to programs: process management, memory, files, devices and security. The kernel is its core part that runs with full privileges and talks to the hardware directly.'],
    ['process-thread', 'What is the difference between a process and a thread?', 'A process is a running program with its own memory space. A thread is a lighter unit of execution inside a process; threads of the same process share its memory, so switching between them is cheaper but shared data needs synchronisation.'],
    ['deadlock', 'What is a deadlock? What are its four conditions?', 'Two or more processes wait forever for resources held by each other. It needs all four conditions at once: mutual exclusion, hold and wait, no preemption and circular wait. Breaking any one prevents it.'],
    ['bankers', 'What is the Banker\'s algorithm?', 'A deadlock-avoidance algorithm. Before granting a request, the OS checks whether the system would still be in a safe state, where some order exists in which every process can finish with the available resources. If not, the request waits.'],
    ['scheduling', 'What are the common CPU scheduling algorithms?', 'FCFS (first come, first served), SJF (shortest job first, optimal average waiting time), priority scheduling, Round Robin (each process gets a fixed time slice, good for time-sharing) and multilevel queue. Preemptive versions can interrupt a running process.'],
    ['paging', 'What is paging? What is virtual memory?', 'Paging splits memory into fixed-size frames and programs into pages of the same size, so a program need not be contiguous in RAM. Virtual memory uses disk space as an extension of RAM, loading pages only when needed (demand paging) so programs larger than RAM can run.'],
    ['page-fault-thrashing', 'What are a page fault and thrashing?', 'A page fault happens when a program uses a page that is not in RAM, so the OS loads it from disk. Thrashing is when the system spends most of its time swapping pages in and out instead of doing work, usually because too many processes are running.'],
    ['semaphore-mutex', 'What is the difference between a semaphore and a mutex?', 'A mutex is a lock that one thread holds at a time and only the owner releases. A semaphore is a counter that allows up to N threads into a section (a binary semaphore allows one) and can be signalled by any thread. Both protect critical sections.'],
    ['context-switch', 'What is a context switch?', 'Saving the state (registers, program counter) of the running process or thread and loading another\'s so the CPU can switch between them. It is pure overhead, so too many switches slow the system.'],
    ['fragmentation', 'What is fragmentation?', 'Wasted memory. Internal fragmentation is unused space inside an allocated block (common with fixed-size blocks). External fragmentation is free memory split into small gaps that cannot satisfy a large request; paging and compaction reduce it.'],
    ['multi', 'What are multiprogramming, multitasking and multiprocessing?', 'Multiprogramming keeps several programs in memory so the CPU always has work. Multitasking rapidly switches between tasks so they appear to run together. Multiprocessing uses two or more CPUs (or cores) running truly in parallel.'],
  ]),

  S('cn', 'Computer networks', 'OSI and TCP/IP models, TCP versus UDP, IP, DNS, HTTP and network devices.', [
    ['osi', 'What are the seven layers of the OSI model?', 'Physical, Data Link, Network, Transport, Session, Presentation and Application. For example, cables and signals work at the physical layer, switches and MAC addresses at the data link layer, routers and IP at the network layer, and TCP/UDP at the transport layer. The TCP/IP model combines them into four layers.'],
    ['tcp-udp', 'What is the difference between TCP and UDP?', 'TCP is connection-oriented and reliable: it uses a three-way handshake, keeps order and resends lost data (used for web, email, file transfer). UDP is connectionless and faster with no guarantee of delivery or order (used for video calls, streaming, gaming and DNS).'],
    ['handshake', 'What is the TCP three-way handshake?', 'The client sends SYN, the server replies SYN-ACK, and the client sends ACK. After that the connection is open and data can flow.'],
    ['ip', 'What is an IP address? IPv4 versus IPv6?', 'A numeric address that identifies a device on a network. IPv4 is 32 bits written as four numbers (192.168.1.10), about 4.3 billion addresses. IPv6 is 128 bits written in hexadecimal groups, giving vastly more addresses.'],
    ['mac', 'What is the difference between a MAC address and an IP address?', 'A MAC address is a fixed 48-bit hardware address of a network card, used inside a local network (data link layer). An IP address is a logical address that can change and is used to route data between networks (network layer).'],
    ['dns', 'What is DNS?', 'The Domain Name System translates names like ouallinone.com into IP addresses so browsers can connect. It works like a phone book, with caching at several levels to make lookups fast.'],
    ['http-https', 'What is the difference between HTTP and HTTPS?', 'HTTP sends data as plain text (port 80). HTTPS encrypts it with TLS (port 443), so passwords and payments cannot be read or changed in transit, and it verifies the website with a certificate.'],
    ['devices', 'What is the difference between a hub, a switch and a router?', 'A hub sends incoming data to every port. A switch learns MAC addresses and sends data only to the right device in a local network. A router connects different networks and forwards packets using IP addresses, such as your home network to the internet.'],
    ['url-flow', 'What happens when you type a URL into a browser?', 'The browser finds the IP address with DNS, opens a TCP connection (and a TLS handshake for HTTPS), sends an HTTP request, the server responds with HTML, and the browser downloads the CSS, JavaScript and images it needs and renders the page.'],
    ['dhcp', 'What is DHCP?', 'A protocol that automatically gives a device an IP address, subnet mask, gateway and DNS server when it joins a network, so you do not configure them by hand.'],
    ['subnet', 'What is subnetting?', 'Dividing a network into smaller networks using a subnet mask (for example /24 = 255.255.255.0). It improves organisation and security and reduces broadcast traffic.'],
    ['firewall', 'What is a firewall?', 'Hardware or software that filters network traffic by rules (allowed ports, addresses, protocols) to block unauthorised access while letting normal traffic through.'],
  ]),

  S('se', 'Software engineering and Agile', 'SDLC, Agile and Scrum roles, testing types and Git basics.', [
    ['sdlc', 'What is the SDLC? What are its phases?', 'The Software Development Life Cycle is the process of building software: requirement gathering and analysis, design, implementation (coding), testing, deployment and maintenance. Models such as Waterfall, V-model, Spiral and Agile organise these phases differently.'],
    ['waterfall-agile', 'What is the difference between Waterfall and Agile?', 'Waterfall runs the phases one after another with requirements fixed at the start, which suits stable, well-defined projects. Agile delivers working software in short iterations (sprints) with continuous customer feedback, so it handles changing requirements better.'],
    ['scrum', 'What is Scrum? Who is a Scrum Master?', 'Scrum is an Agile framework where a small team works in fixed sprints. Roles: the Product Owner (owns and prioritises the product backlog), the Scrum Master (facilitates the process and removes blockers, not a manager) and the Developers.'],
    ['sprint', 'What are a sprint and sprint planning?', 'A sprint is a fixed period, usually one to four weeks, in which the team completes a set of backlog items. In sprint planning the team chooses items from the product backlog for the sprint and breaks them into tasks. Other events are the daily stand-up, sprint review and retrospective.'],
    ['testing-levels', 'What are unit, integration, system and acceptance testing?', 'Unit testing checks individual functions or classes. Integration testing checks that modules work together. System testing checks the complete application against requirements. Acceptance testing (UAT) is done with users or the client before release.'],
    ['black-white', 'What is the difference between black-box and white-box testing?', 'Black-box testing checks behaviour from the outside using inputs and expected outputs, without looking at the code. White-box testing designs tests from the internal code structure, such as covering every branch.'],
    ['git', 'What are Git, commit, push, pull and branch?', 'Git is a version-control system. A commit saves a snapshot locally; push sends commits to a remote repository such as GitHub; pull fetches and merges others\' changes; a branch is an independent line of work merged back later, often through a pull request.'],
    ['ci-cd', 'What is CI/CD?', 'Continuous Integration means every change is automatically built and tested when it is pushed. Continuous Delivery/Deployment means passing changes are automatically prepared for or released to production. Tools: GitHub Actions, Jenkins, GitLab CI.'],
    ['api-rest', 'What is a REST API?', 'A way for programs to talk over HTTP using resources and standard methods: GET (read), POST (create), PUT/PATCH (update) and DELETE, usually exchanging JSON. It is stateless: each request carries everything the server needs.'],
    ['cloud', 'What is cloud computing? IaaS, PaaS and SaaS?', 'Renting computing resources over the internet instead of owning servers. IaaS gives virtual machines and storage (AWS EC2), PaaS gives a platform to deploy code without managing servers (Heroku, Google App Engine), and SaaS gives ready software (Gmail, Microsoft 365).'],
  ]),

  S('ai', 'AI, ML and Gen AI', 'Machine learning basics, evaluation, LLMs, transformers, prompting, RAG and how ChatGPT works.', [
    ['ai-ml-dl', 'What is the difference between AI, machine learning and deep learning?', 'AI is the broad goal of machines doing tasks that need human intelligence. Machine learning is a part of AI where systems learn patterns from data instead of being explicitly programmed. Deep learning is a part of ML that uses neural networks with many layers, behind image recognition and language models.'],
    ['supervised', 'What are supervised, unsupervised and reinforcement learning?', 'Supervised learning trains on labelled examples to predict labels (spam detection, price prediction). Unsupervised learning finds structure in unlabelled data (clustering customers). Reinforcement learning learns by trial and error from rewards (game playing, robotics).'],
    ['regression', 'What is linear regression?', 'A supervised method that predicts a number by fitting a straight line (or plane) y = mx + c to the data, choosing the line that minimises the squared errors. Logistic regression, despite its name, is used for classification.'],
    ['overfitting', 'What is overfitting and how do you prevent it?', 'The model learns the training data, including its noise, so it does well on training data but poorly on new data. Prevent it with more data, simpler models, regularisation, dropout, early stopping and cross-validation.'],
    ['metrics', 'What are accuracy, precision, recall and F1 score?', 'Accuracy is the share of correct predictions. Precision is how many predicted positives are really positive; recall is how many real positives were found. F1 is the harmonic mean of precision and recall, useful when classes are imbalanced.'],
    ['nlp', 'What is NLP?', 'Natural Language Processing lets computers understand and generate human language. Tasks include translation, sentiment analysis, chatbots, summarisation and named-entity recognition. Modern NLP is dominated by transformer models.'],
    ['llm', 'What is a large language model (LLM)?', 'A deep neural network, usually a transformer, trained on huge amounts of text to predict the next token (word piece). From that one skill it can answer questions, write code, summarise and translate. GPT, Claude, Gemini and Llama are examples.'],
    ['chatgpt', 'How does ChatGPT work?', 'It is a transformer-based LLM. First it is pre-trained on large text data to predict the next token. Then it is fine-tuned on example conversations and with human feedback (RLHF) to follow instructions and be helpful and safe. When you chat, it generates the reply one token at a time based on everything in the conversation so far.'],
    ['transformer', 'What is a transformer and attention?', 'A neural-network architecture (2017) built on self-attention: each token looks at every other token and weighs how relevant it is, so the model captures context across the whole input. It processes tokens in parallel, which made training very large models practical.'],
    ['prompt', 'What is prompt engineering?', 'Writing inputs that get better outputs from an LLM: give clear instructions and context, show examples (few-shot prompting), ask for a specific format, and ask it to reason step by step for harder problems.'],
    ['rag', 'What is RAG (retrieval-augmented generation)?', 'Before answering, the system searches a knowledge source (documents stored as embeddings in a vector database) for relevant passages and adds them to the prompt, so the LLM answers from up-to-date or private data with fewer made-up facts.'],
    ['hallucination', 'What is hallucination in Gen AI?', 'When a model produces confident but false or made-up information. Reduce it with RAG, asking for sources, lower temperature, verification steps and human review for important outputs.'],
    ['fine-tune', 'What is the difference between fine-tuning and prompting?', 'Prompting changes only the input, not the model, and is quick and cheap. Fine-tuning further trains the model on task-specific examples to change its behaviour or style; it needs data and compute but can give consistent results for a narrow task.'],
    ['embedding', 'What are embeddings?', 'Lists of numbers (vectors) that represent words, sentences or images so that similar meanings are close together. They power semantic search, recommendations and RAG.'],
  ]),
];
